sources.src/alu.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity alu is
  generic (
    WIDTH : positive := 4
  );
  port (
    a      : in  std_logic_vector(WIDTH-1 downto 0);
    b      : in  std_logic_vector(WIDTH-1 downto 0);
    op     : in  std_logic_vector(2 downto 0);
    result : out std_logic_vector(WIDTH-1 downto 0);
    carry  : out std_logic;
    zero   : out std_logic
  );
end entity alu;

architecture rtl of alu is
begin

  p_comb: process(all)
    variable av : unsigned(WIDTH-1 downto 0);
    variable bv : unsigned(WIDTH-1 downto 0);
    variable sum_ext : unsigned(WIDTH downto 0);
    variable res_v : std_logic_vector(WIDTH-1 downto 0);
    variable carry_v : std_logic;
  begin
    av := unsigned(a);
    bv := unsigned(b);
    -- defaults (avoid latches)
    res_v := (others => '0');
    carry_v := '0';
    case op is
      when "000" => -- ADD: ACC := (ACC + RAM) mod 16; C := carry out of MSB
        sum_ext := ('0' & av) + ('0' & bv);
        res_v := std_logic_vector(sum_ext(WIDTH-1 downto 0));
        carry_v := sum_ext(WIDTH);
      when "001" => -- SUB: ACC := (ACC - RAM) mod 16; C := '1' if a < b (borrow)
        res_v := std_logic_vector(av - bv);
        if av < bv then
          carry_v := '1';
        else
          carry_v := '0';
        end if;
      when "010" => -- AND
        res_v := a and b;
        carry_v := '0';
      when "011" => -- OR
        res_v := a or b;
        carry_v := '0';
      when "100" => -- XOR
        res_v := a xor b;
        carry_v := '0';
      when "101" => -- SHL von a: links schieben, rechts '0'; C := altes MSB
        res_v := std_logic_vector(shift_left(av, 1));
        carry_v := a(WIDTH-1);
      when "110" => -- SHR von a: rechts schieben, links '0'; C := altes LSB
        res_v := std_logic_vector(shift_right(av, 1));
        carry_v := a(0);
      when "111" => -- PASS b
        res_v := b;
        carry_v := '0';
      when others =>
        res_v := (others => '0');
        carry_v := '0';
    end case;
    result <= res_v;
    carry <= carry_v;
    if res_v = std_logic_vector(to_unsigned(0, WIDTH)) then
      zero <= '1';
    else
      zero <= '0';
    end if;
  end process p_comb;

end architecture rtl;

sources.src/control_unit.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity control_unit is
  port (
    clk      : in  std_logic;
    rst      : in  std_logic;
    go       : in  std_logic;
    rom_data : in  std_logic_vector(7 downto 0);
    z_flag   : in  std_logic;
    c_flag   : in  std_logic;
    acc_en   : out std_logic;
    alu_b_sel: out std_logic;
    alu_op   : out std_logic_vector(2 downto 0);
    c_en     : out std_logic;
    halted   : out std_logic;
    ir       : out std_logic_vector(7 downto 0);
    out_en   : out std_logic;
    pc       : out std_logic_vector(3 downto 0);
    ram_addr : out std_logic_vector(3 downto 0);
    ram_we   : out std_logic;
    z_en     : out std_logic
  );
end entity control_unit;

architecture rtl of control_unit is

  -- WAIT is a reserved word in VHDL, therefore S_ prefix.
  -- Mapping to PROMPT.md: S_WAIT=WAIT, S_FETCH=FETCH, etc.
  type state_t is (S_WAIT, S_FETCH, S_DECODE, S_EXECUTE, S_HALT);

  signal state      : state_t;
  signal next_state : state_t;
  signal pc_reg     : std_logic_vector(3 downto 0);
  signal ir_reg     : std_logic_vector(7 downto 0);

  signal opcode     : std_logic_vector(3 downto 0);
  signal jump_taken : std_logic;

begin

  opcode <= ir_reg(7 downto 4);

  -- Jump decision (only evaluated in EXECUTE)
  p_jump: process(all)
  begin
    jump_taken <= '0';
    if state = S_EXECUTE then
      case opcode is
        when x"B" =>
          jump_taken <= '1';
        when x"C" =>
          if z_flag = '1' then
            jump_taken <= '1';
          end if;
        when x"D" =>
          if c_flag = '1' then
            jump_taken <= '1';
          end if;
        when others =>
          jump_taken <= '0';
      end case;
    end if;
  end process p_jump;

  -- Next-state logic (combinational, go only used in S_WAIT)
  p_next: process(all)
  begin
    next_state <= state;
    case state is
      when S_WAIT =>
        if go = '1' then
          next_state <= S_FETCH;
        else
          next_state <= S_WAIT;
        end if;
      when S_FETCH =>
        next_state <= S_DECODE;
      when S_DECODE =>
        next_state <= S_EXECUTE;
      when S_EXECUTE =>
        if opcode = x"F" then
          next_state <= S_HALT;
        else
          next_state <= S_WAIT;
        end if;
      when S_HALT =>
        next_state <= S_HALT;
      when others =>
        next_state <= S_WAIT;
    end case;
  end process p_next;

  -- State / PC / IR registers, synchronous active-high reset
  p_seq: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        state   <= S_WAIT;
        pc_reg  <= (others => '0');
        ir_reg  <= (others => '0');
      else
        state <= next_state;
        case state is
          when S_FETCH =>
            ir_reg <= rom_data;
            pc_reg <= std_logic_vector(unsigned(pc_reg) + 1);
          when S_EXECUTE =>
            if jump_taken = '1' then
              pc_reg <= ir_reg(3 downto 0);
            end if;
          when others =>
            null;
        end case;
      end if;
    end if;
  end process p_seq;

  -- Control-signal outputs (combinational, active only in EXECUTE)
  -- Convention: alu_b_sel = '0' selects RAM data, '1' selects immediate
  -- operand IR(3..0) (ALUSrc-like). cpu_core muxes ALU-B accordingly.
  p_out: process(all)
  begin
    -- defaults (avoid latches)
    acc_en    <= '0';
    alu_b_sel <= '0';
    alu_op    <= "000";
    c_en      <= '0';
    out_en    <= '0';
    ram_we    <= '0';
    z_en      <= '0';

    if state = S_EXECUTE then
      case opcode is
        when x"0" => -- NOP
          null;
        when x"1" => -- LDI n: ACC := n (PASS imm); Z neu; C unveraendert
          acc_en    <= '1';
          z_en      <= '1';
          alu_op    <= "111";
          alu_b_sel <= '1';
        when x"2" => -- LDA a: ACC := RAM[a] (PASS ram); Z neu
          acc_en    <= '1';
          z_en      <= '1';
          alu_op    <= "111";
          alu_b_sel <= '0';
        when x"3" => -- STA a: RAM[a] := ACC
          ram_we    <= '1';
        when x"4" => -- ADD a
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "000";
          alu_b_sel <= '0';
        when x"5" => -- SUB a
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "001";
          alu_b_sel <= '0';
        when x"6" => -- AND a
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "010";
          alu_b_sel <= '0';
        when x"7" => -- OR a
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "011";
          alu_b_sel <= '0';
        when x"8" => -- XOR a
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "100";
          alu_b_sel <= '0';
        when x"9" => -- SHL
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "101";
          alu_b_sel <= '0';
        when x"A" => -- SHR
          acc_en    <= '1';
          z_en      <= '1';
          c_en      <= '1';
          alu_op    <= "110";
          alu_b_sel <= '0';
        when x"B" => -- JMP t
          null;
        when x"C" => -- JZ t
          null;
        when x"D" => -- JC t
          null;
        when x"E" => -- OUT: OUT := ACC
          out_en    <= '1';
        when x"F" => -- HLT
          null;
        when others =>
          null;
      end case;
    end if;
  end process p_out;

  -- Registered-state reflections
  pc <= pc_reg;
  ir <= ir_reg;

  -- RAM address: operand of current instruction (valid in EXECUTE;
  -- RAM read is combinational, write is gated by ram_we)
  ram_addr <= ir_reg(3 downto 0);

  halted <= '1' when state = S_HALT else '0';

end architecture rtl;

sources.src/cpu_core.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity cpu_core is
  port (
    clk       : in  std_logic;
    rst       : in  std_logic;
    go        : in  std_logic;
    out_value : out std_logic_vector(3 downto 0);
    acc       : out std_logic_vector(3 downto 0);
    pc        : out std_logic_vector(3 downto 0);
    z         : out std_logic;
    c         : out std_logic;
    halted    : out std_logic
  );
end entity cpu_core;

architecture rtl of cpu_core is

  signal acc_reg      : std_logic_vector(3 downto 0);
  signal out_reg      : std_logic_vector(3 downto 0);
  signal z_reg        : std_logic;
  signal c_reg        : std_logic;

  signal ir_sig       : std_logic_vector(7 downto 0);
  signal pc_sig       : std_logic_vector(3 downto 0);
  signal rom_data_sig : std_logic_vector(7 downto 0);

  signal ram_addr_sig : std_logic_vector(3 downto 0);
  signal ram_rdata    : std_logic_vector(3 downto 0);
  signal ram_we_sig   : std_logic;

  signal alu_a      : std_logic_vector(3 downto 0);
  signal alu_b      : std_logic_vector(3 downto 0);
  signal alu_op     : std_logic_vector(2 downto 0);
  signal alu_b_sel  : std_logic;
  signal alu_result : std_logic_vector(3 downto 0);
  signal alu_carry  : std_logic;
  signal alu_zero   : std_logic;

  signal acc_en_sig : std_logic;
  signal c_en_sig   : std_logic;
  signal z_en_sig   : std_logic;
  signal out_en_sig : std_logic;
  signal halted_sig : std_logic;

begin

  -- ALU-B-Multiplexer: '0' = RAM-Daten, '1' = Immediate IR(3..0)
  p_alu_b_mux: process(all)
  begin
    if alu_b_sel = '1' then
      alu_b <= ir_sig(3 downto 0);
    else
      alu_b <= ram_rdata;
    end if;
  end process p_alu_b_mux;

  alu_a <= acc_reg;

  -- ACC / Z / C / OUT-Register, synchroner Reset active high
  p_regs: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        acc_reg <= (others => '0');
        z_reg   <= '0';
        c_reg   <= '0';
        out_reg <= (others => '0');
      else
        if acc_en_sig = '1' then
          acc_reg <= alu_result;
        end if;
        if z_en_sig = '1' then
          z_reg <= alu_zero;
        end if;
        if c_en_sig = '1' then
          c_reg <= alu_carry;
        end if;
        if out_en_sig = '1' then
          out_reg <= acc_reg;
        end if;
      end if;
    end if;
  end process p_regs;

  u_control: entity work.control_unit
    port map (
      clk       => clk,
      rst       => rst,
      go        => go,
      rom_data  => rom_data_sig,
      z_flag    => z_reg,
      c_flag    => c_reg,
      acc_en    => acc_en_sig,
      alu_b_sel => alu_b_sel,
      alu_op    => alu_op,
      c_en      => c_en_sig,
      halted    => halted_sig,
      ir        => ir_sig,
      out_en    => out_en_sig,
      pc        => pc_sig,
      ram_addr  => ram_addr_sig,
      ram_we    => ram_we_sig,
      z_en      => z_en_sig
    );

  u_alu: entity work.alu
    generic map (
      WIDTH => 4
    )
    port map (
      a      => alu_a,
      b      => alu_b,
      op     => alu_op,
      result => alu_result,
      carry  => alu_carry,
      zero   => alu_zero
    );

  u_rom: entity work.program_rom
    port map (
      addr => pc_sig,
      data => rom_data_sig
    );

  u_ram: entity work.data_ram
    generic map (
      ADDR_WIDTH => 4,
      DATA_WIDTH => 4
    )
    port map (
      addr  => ram_addr_sig,
      clk   => clk,
      rst   => rst,
      rdata => ram_rdata,
      wdata => acc_reg,
      we    => ram_we_sig
    );

  acc       <= acc_reg;
  out_value <= out_reg;
  pc        <= pc_sig;
  z         <= z_reg;
  c         <= c_reg;
  halted    <= halted_sig;

end architecture rtl;

sources.src/data_ram.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity data_ram is
  generic (
    ADDR_WIDTH : integer := 4;
    DATA_WIDTH : integer := 4
  );
  port (
    addr  : in  std_logic_vector(ADDR_WIDTH-1 downto 0);
    clk   : in  std_logic;
    rst   : in  std_logic;
    rdata : out std_logic_vector(DATA_WIDTH-1 downto 0);
    wdata : in  std_logic_vector(DATA_WIDTH-1 downto 0);
    we    : in  std_logic
  );
end entity data_ram;

architecture rtl of data_ram is
  type ram_t is array (0 to 2**ADDR_WIDTH - 1) of std_logic_vector(DATA_WIDTH-1 downto 0);
  signal mem : ram_t := (others => (others => '0'));
begin

  p_write: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        mem <= (others => (others => '0'));
      elsif we = '1' then
        mem(to_integer(unsigned(addr))) <= wdata;
      end if;
    end if;
  end process p_write;

  rdata <= mem(to_integer(unsigned(addr)));

end architecture rtl;

