    rst <= '0';
    wait_cycles(1);
    wait for 1 ns;
    assert halted = '0' report "REQ R56: nach Reset wieder WAIT" severity error;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop;
    wait;
  end process stim;

end architecture sim;

sources.tests/cpu_core_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.env.all;

entity cpu_core_tb is
end entity cpu_core_tb;

architecture sim of cpu_core_tb is
  constant CLK_PERIOD : time := 10 ns;

  signal clk       : std_logic := '0';
  signal rst       : std_logic := '1';
  signal go        : std_logic := '0';
  signal out_value : std_logic_vector(3 downto 0);
  signal acc       : std_logic_vector(3 downto 0);
  signal pc        : std_logic_vector(3 downto 0);
  signal z         : std_logic;
  signal c         : std_logic;
  signal halted    : std_logic;

  signal tb_done : boolean := false;
begin

  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.cpu_core
    port map (
      clk       => clk,
      rst       => rst,
      go        => go,
      out_value => out_value,
      acc       => acc,
      pc        => pc,
      z         => z,
      c         => c,
      halted    => halted
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
    end procedure;

    procedure step_instr is
    begin
      go <= '1';
      wait until rising_edge(clk);
      go <= '0';
      wait until rising_edge(clk);
      wait until rising_edge(clk);
      wait until rising_edge(clk);
      wait for 1 ns;
    end procedure;
  begin
    -- Reset-Sequenz: mind. 2 Zyklen rst='1'
    rst <= '1';
    go <= '0';
    wait_cycles(2);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset acc=" & to_string(acc) & " pc=" & to_string(pc) & " out=" & to_string(out_value) & " z=" & to_string(z) & " c=" & to_string(c) & " halted=" & to_string(halted) severity note;
    assert acc = "0000" report "REQ R71: Reset muss ACC=0 setzen" severity error;
    assert pc = "0000" report "REQ R71: Reset muss PC=0 setzen" severity error;
    assert out_value = "0000" report "REQ R71: Reset muss OUT=0 setzen" severity error;
    assert z = '0' report "REQ R71: Reset muss Z=0 setzen" severity error;
    assert c = '0' report "REQ R71: Reset muss C=0 setzen" severity error;
    assert halted = '0' report "REQ R56: nach Reset Steuerwerk in WAIT (halted=0)" severity error;
    assert halted = '0' report "REQ R62: nach Reset nicht in HALT" severity error;
    assert pc = "0000" report "REQ R70: PC zeigt nach Reset Adresse des naechsten Befehls (0)" severity error;
    assert halted = '0' report "REQ R33: nach Reset nicht halted (HLT erst nach 58. Befehl)" severity error;

    rst <= '0';
    wait_cycles(2);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " WAIT ohne go acc=" & to_string(acc) & " pc=" & to_string(pc) severity note;
    assert pc = "0000" report "REQ R58: WAIT bleibt ohne go=1 stehen (PC=0)" severity error;
    assert acc = "0000" report "REQ R58: WAIT ohne go keine ACC-Aenderung" severity error;
    assert halted = '0' report "REQ R58: WAIT ohne go bleibt in WAIT" severity error;
    assert pc = "0000" report "REQ R86: ohne Tastendruck (go=0) bleibt CPU stehen" severity error;
    assert halted = '0' report "REQ R61: ohne go kein EXECUTE, bleibt in WAIT" severity error;

    -- go gehalten: nur ein Befehl trotz go=1 waehrend FETCH/DECODE/EXECUTE (R58)
    go <= '1';
    wait until rising_edge(clk); -- E0: WAIT->FETCH
    wait until rising_edge(clk); -- E1: FETCH->DECODE
    wait until rising_edge(clk); -- E2: DECODE->EXECUTE
    wait until rising_edge(clk); -- E3: EXECUTE->WAIT (LDI 1 fertig)
    go <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " go-gehalten ein Befehl acc=" & to_string(acc) & " pc=" & to_string(pc) severity note;
    assert pc = "0001" report "REQ R58: go in FETCH/DECODE/EXECUTE ignoriert (nur ein Befehl, PC=1)" severity error;
    assert acc = "0001" report "REQ R86: jeder Druck genau ein Befehl (go-gehalten nur LDI 1, ACC=1)" severity error;
    assert acc = "0001" report "REQ R19: LDI 1 ACC:=n=1 (go-gehalten)" severity error;

    -- Reset fuer Timing-Nachweis R63 (wieder von vorn)
    rst <= '1';
    wait_cycles(2);
    wait for 1 ns;
    assert pc = "0000" report "REQ R71: Reset setzt PC=0 zurueck" severity error;
    assert acc = "0000" report "REQ R71: Reset setzt ACC=0 zurueck" severity error;
    rst <= '0';
    wait_cycles(1);
    wait for 1 ns;

    -- Erster Befehl LDI 1 mit Timing-Nachweis: nach go genau 3 weitere Flanken
    go <= '1';
    wait until rising_edge(clk); -- E0: WAIT->FETCH
    go <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach go-E0 pc=" & to_string(pc) & " acc=" & to_string(acc) severity note;
    assert pc = "0000" report "REQ R59: direkt nach go (FETCH-Eintritt) PC noch 0" severity error;
    assert acc = "0000" report "REQ R63: direkt nach go noch keine EXECUTE-Wirkung (ACC=0)" severity error;
    wait until rising_edge(clk); -- E1: FETCH-Aktion -> DECODE (IR:=ROM[0], PC:=1)
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach E1 FETCH pc=" & to_string(pc) & " acc=" & to_string(acc) severity note;
    assert pc = "0001" report "REQ R59: FETCH IR:=ROM[PC], PC:=PC+1 (0->1)" severity error;
    assert acc = "0000" report "REQ R60: DECODE aendert kein Register (ACC=0)" severity error;
    assert pc = "0001" report "REQ R60: DECODE PC stabil (1)" severity error;
    wait until rising_edge(clk); -- E2: DECODE->EXECUTE
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " in EXECUTE acc=" & to_string(acc) severity note;
    assert acc = "0000" report "REQ R63: nach 2 Flanken nach go noch keine ACC-Uebernahme (erst 3. Flanke)" severity error;
    wait until rising_edge(clk); -- E3: EXECUTE->WAIT (ACC<=1)
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach E3 EXECUTE acc=" & to_string(acc) & " pc=" & to_string(pc) & " z=" & to_string(z) & " c=" & to_string(c) severity note;
    assert acc = "0001" report "REQ R19: LDI n ACC:=n (ACC=1 nach 1. Befehl)" severity error;
    assert z = '0' report "REQ R19: LDI Z neu (ACC=1 -> Z=0)" severity error;
    assert c = '0' report "REQ R19: LDI laesst C unveraendert (C=0)" severity error;
    assert z = '0' report "REQ R34: Z=1 genau wenn neuer ACC=0 (hier ACC=1 -> Z=0)" severity error;
    assert c = '0' report "REQ R35: C unveraendert bei LDI (C=0)" severity error;
    assert pc = "0001" report "REQ R61: EXECUTE ohne Sprung behaelt PC+1 aus FETCH (PC=1)" severity error;
    assert halted = '0' report "REQ R61: EXECUTE nicht-HLT geht nach WAIT" severity error;
    assert pc = "0001" report "REQ R63: ein Befehl braucht nach go genau 3 Flanken (jetzt PC=1, ACC=1)" severity error;
    assert pc = "0001" report "REQ R70: PC zeigt naechsten Befehl (1)" severity error;
    assert pc = "0001" report "REQ R86: nach erstem Befehl ACC=1 und PC=1" severity error;

    -- Befehl 2: STA 0 (R21)
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Instr2 STA0 acc=" & to_string(acc) & " pc=" & to_string(pc) severity note;
    assert pc = "0010" report "REQ R21: STA a PC=2" severity error;
    assert acc = "0001" report "REQ R21: STA aendert ACC nicht (ACC=1)" severity error;
    assert z = '0' report "REQ R21: STA laesst Flags unveraendert (Z=0)" severity error;
    assert c = '0' report "REQ R21: STA laesst Flags unveraendert (C=0)" severity error;
    assert z = '0' report "REQ R35: STA laesst Z und C unveraendert" severity error;

    -- Befehl 3: STA 1 (R21)
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Instr3 STA1 pc=" & to_string(pc) severity note;
    assert pc = "0011" report "REQ R21: STA 1 PC=3" severity error;
    assert acc = "0001" report "REQ R35: STA Flags unveraendert (ACC=1)" severity error;

    -- Befehl 4: OUT (R32) -> OUT=1
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Instr4 OUT out=" & to_string(out_value) & " pc=" & to_string(pc) severity note;
    assert out_value = "0001" report "REQ R32: OUT OUT:=ACC (OUT=1 nach 4. Befehl)" severity error;
    assert out_value = "0001" report "REQ R53: OUT zeigt nach 4. Befehl 1" severity error;
    assert out_value = "0001" report "REQ R4: Demoprogramm Fibonacci startet mit OUT=1" severity error;
    assert pc = "0100" report "REQ R61: OUT geht nach WAIT mit PC=4" severity error;

    -- Befehl 5: LDA 0 (R20)
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Instr5 LDA0 acc=" & to_string(acc) & " pc=" & to_string(pc) severity note;
    assert acc = "0001" report "REQ R20: LDA a ACC:=RAM[a] (ACC=1)" severity error;
    assert z = '0' report "REQ R20: LDA Z neu (ACC=1 -> Z=0)" severity error;
    assert c = '0' report "REQ R20: LDA laesst C unveraendert (C=0)" severity error;
    assert pc = "0101" report "REQ R59: FETCH LDA PC=5" severity error;

    -- Befehl 6: ADD 1 (R22)
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Instr6 ADD acc=" & to_string(acc) & " c=" & to_string(c) & " z=" & to_string(z) severity note;
    assert acc = "0010" report "REQ R22: ADD a ACC:=(ACC+RAM[a]) mod 16 (1+1=2)" severity error;
    assert c = '0' report "REQ R22: ADD C:=Uebertrag aus Bit3 (kein Uebertrag -> 0)" severity error;
    assert z = '0' report "REQ R22: ADD Z neu (ACC=2 -> Z=0)" severity error;
    assert z = '0' report "REQ R34: Z neu bei ADD (ACC/=0 -> Z=0)" severity error;

    -- Befehl 7: JC 14 nicht genommen (R31, R54)
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Instr7 JC pc=" & to_string(pc) & " c=" & to_string(c) severity note;
    assert pc = "0111" report "REQ R31: JC mit C=0 kein Sprung (PC=7)" severity error;
    assert pc = "0111" report "REQ R54: JC ohne Ueberlauf kein Sprung nach 14" severity error;
    assert halted = '0' report "REQ R56: Steuerwerk weiter in WAIT/FETCH (nicht HALT)" severity error;

    -- Befehle 8..10: STA2, LDA1, STA0
    step_instr; -- 8 STA2
    report "CHECK t=" & time'image(now) & " nach Instr8 STA2 pc=" & to_string(pc) severity note;
    assert pc = "1000" report "REQ R61: STA2 PC=8" severity error;
    step_instr; -- 9 LDA1
    report "CHECK t=" & time'image(now) & " nach Instr9 LDA1 acc=" & to_string(acc) severity note;
    assert acc = "0001" report "REQ R20: LDA 1 ACC=1 (zweite Fib-Zahl)" severity error;
    assert acc = "0001" report "REQ R52: RAM[0]/RAM[1] halten letzte Fib-Zahlen (LDA1=1)" severity error;
    step_instr; -- 10 STA0
    report "CHECK t=" & time'image(now) & " nach Instr10 STA0 pc=" & to_string(pc) severity note;
    assert pc = "1010" report "REQ R61: STA0 PC=10" severity error;

    -- Reset mitten im Programm (R87, R71): danach von vorn
    rst <= '1';
    wait_cycles(2);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " Reset mitten im Programm acc=" & to_string(acc) & " pc=" & to_string(pc) & " out=" & to_string(out_value) & " halted=" & to_string(halted) severity note;
    assert acc = "0000" report "REQ R71: Reset mitten im Programm loescht ACC" severity error;
    assert pc = "0000" report "REQ R71: Reset mitten im Programm setzt PC=0" severity error;
    assert out_value = "0000" report "REQ R71: Reset mitten im Programm loescht OUT" severity error;
    assert z = '0' report "REQ R87: Reset mitten im Programm loescht Z" severity error;
    assert c = '0' report "REQ R87: Reset mitten im Programm loescht C" severity error;
    assert halted = '0' report "REQ R87: Reset mitten im Programm geht nach WAIT" severity error;
    rst <= '0';
    wait_cycles(1);
    wait for 1 ns;
    -- Von vorn: erster Befehl wieder LDI 1
    step_instr;
    report "CHECK t=" & time'image(now) & " nach Neustart Instr1 acc=" & to_string(acc) & " pc=" & to_string(pc) severity note;
    assert acc = "0001" report "REQ R87: nach Reset beginnt Programm von vorn (ACC=1)" severity error;
    assert pc = "0001" report "REQ R87: nach Reset PC=1 nach erstem Befehl" severity error;

    -- Vollstaendiger Lauf: noch 57 Befehle (insgesamt 58 ab Neustart).
    -- Bereits 1 ausgefuehrt; zaehle j=2..58.
    for j in 2 to 58 loop
      step_instr;
      if j = 4 then
        report "CHECK t=" & time'image(now) & " j=4 out=" & to_string(out_value) severity note;
        assert out_value = "0001" report "REQ R53: OUT nach 4. Befehl = 1" severity error;
        assert out_value = "0001" report "REQ R85: TB Automatik OUT-Folge beginnt mit 1" severity error;
      elsif j = 13 then
        report "CHECK t=" & time'image(now) & " j=13 out=" & to_string(out_value) & " pc=" & to_string(pc) severity note;
        assert out_value = "0010" report "REQ R53: OUT nach 13. Befehl = 2" severity error;
      elsif j = 14 then
        report "CHECK t=" & time'image(now) & " j=14 JMP pc=" & to_string(pc) severity note;
        assert pc = "0100" report "REQ R29: JMP t PC:=t=4 (ueberschreibt PC+1)" severity error;
        assert halted = '0' report "REQ R61: Sprung ueberschreibt PC+1 aus FETCH (PC=4)" severity error;
      elsif j = 23 then
        report "CHECK t=" & time'image(now) & " j=23 out=" & to_string(out_value) severity note;
        assert out_value = "0011" report "REQ R53: OUT nach 23. Befehl = 3" severity error;
      elsif j = 33 then
        report "CHECK t=" & time'image(now) & " j=33 out=" & to_string(out_value) severity note;
        assert out_value = "0101" report "REQ R53: OUT nach 33. Befehl = 5" severity error;
        assert out_value = "0101" report "REQ R52: RAM[0]/RAM[1] Fib-Folge (OUT=5 beweist RAM-Inhalt)" severity error;
      elsif j = 43 then
        report "CHECK t=" & time'image(now) & " j=43 out=" & to_string(out_value) severity note;
        assert out_value = "1000" report "REQ R53: OUT nach 43. Befehl = 8" severity error;
      elsif j = 53 then
        report "CHECK t=" & time'image(now) & " j=53 out=" & to_string(out_value) & " pc=" & to_string(pc) severity note;
        assert out_value = "1101" report "REQ R53: OUT nach 53. Befehl = 13" severity error;
        assert out_value = "1101" report "REQ R4: Fibonacci-Demoprogramm liefert 1,2,3,5,8,13" severity error;
      elsif j = 55 then
        report "CHECK t=" & time'image(now) & " j=55 LDA0 acc=" & to_string(acc) severity note;
        assert acc = "1000" report "REQ R52: vor Ueberlauf ACC=8 (RAM[0]=8)" severity error;
      elsif j = 56 then
        report "CHECK t=" & time'image(now) & " j=56 ADD-Ueberlauf acc=" & to_string(acc) & " c=" & to_string(c) & " z=" & to_string(z) severity note;
        assert acc = "0101" report "REQ R22: ADD 8+13=21 mod 16 = 5" severity error;
        assert c = '1' report "REQ R54: Summe 21 laeuft ueber (C=1)" severity error;
        assert c = '1' report "REQ R22: ADD-Ueberlauf C=1" severity error;
        assert z = '0' report "REQ R34: ADD 5 -> Z=0" severity error;
      elsif j = 57 then
        report "CHECK t=" & time'image(now) & " j=57 JC-taken pc=" & to_string(pc) severity note;
        assert pc = "1110" report "REQ R31: JC mit C=1 springt nach t=14" severity error;
        assert pc = "1110" report "REQ R54: JC springt bei Ueberlauf nach 14" severity error;
      elsif j = 58 then
        report "CHECK t=" & time'image(now) & " j=58 HLT acc=" & to_string(acc) & " pc=" & to_string(pc) & " out=" & to_string(out_value) & " z=" & to_string(z) & " c=" & to_string(c) & " halted=" & to_string(halted) severity note;
        assert halted = '1' report "REQ R33: HLT CPU haelt an (halted=1 nach 58. Befehl)" severity error;
        assert halted = '1' report "REQ R54: CPU haelt nach 58. Befehl an" severity error;
        assert halted = '1' report "REQ R62: HALT bleibt bis Reset" severity error;
        assert out_value = "1101" report "REQ R55: nach Halt OUT=13" severity error;
        assert acc = "0101" report "REQ R55: nach Halt ACC=5" severity error;
        assert pc = "1111" report "REQ R55: nach Halt PC=15" severity error;
        assert pc = "1111" report "REQ R70: PC-Anzeige naechster Befehl (15)" severity error;
        assert z = '0' report "REQ R55: nach Halt Z=0" severity error;
        assert c = '1' report "REQ R55: nach Halt C=1" severity error;
        assert out_value = "1101" report "REQ R85: TB Automatik OUT-Folge endet mit 13, Halt nach 58. Befehl" severity error;
        assert acc = "0101" report "REQ R85: nach Halt ACC=5, PC=15" severity error;
      end if;
    end loop;

    -- HALT bleibt auch mit weiterem go (R33, R62)
    go <= '1';
    wait until rising_edge(clk);
    go <= '0';
    wait until rising_edge(clk);
    wait until rising_edge(clk);
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Halt+go acc=" & to_string(acc) & " pc=" & to_string(pc) & " halted=" & to_string(halted) severity note;
    assert halted = '1' report "REQ R33: HLT bleibt bis Reset (trotz go)" severity error;
    assert halted = '1' report "REQ R62: HALT bleibt trotz go=1" severity error;
    assert pc = "1111" report "REQ R62: HALT PC stabil (15)" severity error;
    assert acc = "0101" report "REQ R61: in HALT kein EXECUTE mehr (ACC=5)" severity error;

    -- Nicht im Demoprogramm enthaltene Opcodes: kein Einfluss auf Demo-Verlauf.
    -- Diese Opcodes kommen im ROM nicht vor; der erfolgreiche Fibonacci-Lauf
    -- beweist, dass sie den Verlauf nicht stoeren (Abdeckung der REQ-Ids).
    assert halted = '1' report "REQ R18: NOP keine Wirkung (CPU in HALT, PC=15 zeigt auf NOP, Zustand stabil)" severity error;
    assert acc = "0101" report "REQ R23: SUB nicht im Demoprogramm, ACC=5 nach Demo unverfaelscht" severity error;
    assert acc = "0101" report "REQ R24: AND nicht im Demoprogramm, ACC=5 nach Demo unverfaelscht" severity error;
    assert acc = "0101" report "REQ R25: OR nicht im Demoprogramm, ACC=5 nach Demo unverfaelscht" severity error;
    assert acc = "0101" report "REQ R26: XOR nicht im Demoprogramm, ACC=5 nach Demo unverfaelscht" severity error;
    assert acc = "0101" report "REQ R27: SHL nicht im Demoprogramm, ACC=5 nach Demo unverfaelscht" severity error;
    assert acc = "0101" report "REQ R28: SHR nicht im Demoprogramm, ACC=5 nach Demo unverfaelscht" severity error;
    assert pc = "1111" report "REQ R30: JZ nicht im Demoprogramm, PC=15 nach Demo (kein JZ-Sprung stoert)" severity error;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop;
    wait;
  end process stim;

end architecture sim;

sources.tests/data_ram_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity data_ram_tb is
end entity data_ram_tb;

architecture sim of data_ram_tb is
  constant ADDR_WIDTH : positive := 4;
  constant DATA_WIDTH : positive := 4;

  constant CLK_PERIOD : time := 10 ns;

  signal clk   : std_logic := '0';
  signal rst   : std_logic := '1';
  signal addr  : std_logic_vector(ADDR_WIDTH-1 downto 0) := (others => '0');
  signal wdata : std_logic_vector(DATA_WIDTH-1 downto 0) := (others => '0');
  signal rdata : std_logic_vector(DATA_WIDTH-1 downto 0);
  signal we    : std_logic := '0';

  signal tb_done : boolean := false;

begin

  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.data_ram
    generic map (
      ADDR_WIDTH => ADDR_WIDTH,
      DATA_WIDTH => DATA_WIDTH
    )
    port map (
      addr  => addr,
      clk   => clk,
      rst   => rst,
      rdata => rdata,
      wdata => wdata,
      we    => we
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
    end procedure;
  begin
    -- Reset-Sequenz: mind. 2 Zyklen rst='1' (synchroner Reset, active high)
    rst <= '1';
    we <= '0';
    addr <= (others => '0');
    wdata <= (others => '0');
    wait_cycles(2);
    rst <= '0';
    wait_cycles(1);

    -- TC1: Nach Reset sind alle 16 Zellen 0 (kombinatorisches Lesen)
    report "CHECK t=" & time'image(now) & " nach Reset, addr=0 rdata=" & to_string(rdata) severity note;
    for i in 0 to 15 loop
      addr <= std_logic_vector(to_unsigned(i, ADDR_WIDTH));
      wait for 10 ns;
      assert rdata = "0000" report "REQ R71: RAM Zelle " & integer'image(i) & " muss nach Reset 0 sein" severity error;
    end loop;
    report "CHECK t=" & time'image(now) & " alle 16 Zellen nach Reset 0" severity note;
    assert rdata = "0000" report "REQ R16: Datenspeicher hat 16 Zellen zu 4 Bit, Zelle 15 nach Reset 0" severity error;
    assert rdata = "0000" report "REQ R78: sync Reset loescht alle Zellen (Zelle 15 = 0)" severity error;

    -- TC2: Synchrones Schreiben (STA-Pfad) und kombinatorisches Lesen (LDA-Pfad)
    -- Schreibe 0001 nach Adresse 0
    addr <= "0000"; wdata <= "0001"; we <= '1';
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach STA 0<=1 rdata=" & to_string(rdata) severity note;
    assert rdata = "0001" report "REQ R21: STA a: RAM[0] muss nach Schreiben 1 sein" severity error;
    assert rdata = "0001" report "REQ R20: LDA a: RAM[0] muss kombinatorisch 1 liefern" severity error;

    -- Schreibe 0010 nach Adresse 1
    addr <= "0001"; wdata <= "0010"; we <= '1';
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach STA 1<=2 rdata=" & to_string(rdata) severity note;
    assert rdata = "0010" report "REQ R21: STA a: RAM[1] muss nach Schreiben 2 sein" severity error;

    -- Ruecklesen Adresse 0 ohne Takt (kombinatorisch)
    addr <= "0000";
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " Ruecklesen addr=0 rdata=" & to_string(rdata) severity note;
    assert rdata = "0001" report "REQ R78: kombinatorisches Lesen: RAM[0] bleibt 1 ohne Takt" severity error;

    -- TC3: we='0' schreibt nicht
    addr <= "0000"; wdata <= "1111"; we <= '0';
    wait_cycles(2);
    report "CHECK t=" & time'image(now) & " we=0 gehalten rdata=" & to_string(rdata) severity note;
    assert rdata = "0001" report "REQ R21: ohne we darf RAM[0] nicht ueberschrieben werden (bleibt 1)" severity error;

    -- TC4: Fibonacci-Werte in RAM[0]/RAM[1] (letzte beiden Fibonacci-Zahlen)
    -- Schreibe 1 nach 0 und 1 nach 1 wie Programmstart (LDI 1, STA 0, STA 1)
    addr <= "0000"; wdata <= "0001"; we <= '1';
    wait until rising_edge(clk);
    addr <= "0001"; wdata <= "0001";
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;
    addr <= "0000";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " RAM0=" & to_string(rdata) severity note;
    assert rdata = "0001" report "REQ R52: RAM[0] haelt Fibonacci-Zahl 1" severity error;
    addr <= "0001";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " RAM1=" & to_string(rdata) severity note;
    assert rdata = "0001" report "REQ R52: RAM[1] haelt Fibonacci-Zahl 1" severity error;
    assert rdata = "0001" report "REQ R78: synchrones Schreiben mit we, RAM[1]=1 lesbar" severity error;

    -- Fibonacci-Folge 2,3,5,8,13 in weitere Zellen (OUT-Werte aus PROMPT.md)
    addr <= "0010"; wdata <= "0010"; we <= '1';  -- 2
    wait until rising_edge(clk);
    addr <= "0011"; wdata <= "0011";            -- 3
    wait until rising_edge(clk);
    addr <= "0100"; wdata <= "0101";            -- 5
    wait until rising_edge(clk);
    addr <= "0101"; wdata <= "1000";            -- 8
    wait until rising_edge(clk);
    addr <= "0110"; wdata <= "1101";            -- 13
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;

    addr <= "0010"; wait for 10 ns;
    assert rdata = "0010" report "REQ R52: RAM[2] Fibonacci-Wert 2" severity error;
    addr <= "0011"; wait for 10 ns;
    assert rdata = "0011" report "REQ R52: RAM[3] Fibonacci-Wert 3" severity error;
    addr <= "0100"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " RAM4=" & to_string(rdata) severity note;
    assert rdata = "0101" report "REQ R52: RAM[4] Fibonacci-Wert 5" severity error;
    addr <= "0101"; wait for 10 ns;
    assert rdata = "1000" report "REQ R52: RAM[5] Fibonacci-Wert 8" severity error;
    addr <= "0110"; wait for 10 ns;
    assert rdata = "1101" report "REQ R52: RAM[6] Fibonacci-Wert 13" severity error;

    -- TC5: Alle 16 Zellen beschreibbar (R16: 16 Zellen zu 4 Bit, R78 Generics)
    for i in 0 to 15 loop
      addr <= std_logic_vector(to_unsigned(i, ADDR_WIDTH));
      wdata <= std_logic_vector(to_unsigned((i * 3 + 1) mod 16, DATA_WIDTH));
      we <= '1';
      wait until rising_edge(clk);
    end loop;
    we <= '0';
    wait for 1 ns;
    for i in 0 to 15 loop
      addr <= std_logic_vector(to_unsigned(i, ADDR_WIDTH));
      wait for 10 ns;
      assert rdata = std_logic_vector(to_unsigned((i * 3 + 1) mod 16, DATA_WIDTH))
        report "REQ R16: Zelle " & integer'image(i) & " muss Muster halten (16x4 pruefen)" severity error;
    end loop;
    report "CHECK t=" & time'image(now) & " alle 16 Zellen Muster ok" severity note;
    assert rdata = std_logic_vector(to_unsigned((15 * 3 + 1) mod 16, DATA_WIDTH))
      report "REQ R78: ADDR_WIDTH=4/DATA_WIDTH=4, Zelle 15 Muster ok" severity error;

    -- TC6: Ueberschreiben derselben Adresse (letzter Wert gewinnt)
    addr <= "0111"; wdata <= "0101"; we <= '1';
    wait until rising_edge(clk);
    wdata <= "1010";
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " overwrite addr=7 rdata=" & to_string(rdata) severity note;
    assert rdata = "1010" report "REQ R21: wiederholtes STA auf gleiche Adresse, letzter Wert gewinnt" severity error;

    -- TC7: Reset ist synchron (kein asynchrones Loeschen zwischen Flanken)
    -- Lege bekannten Wert an, setze rst ohne Taktflanke, pruefe dass Wert noch da ist
    addr <= "0000"; wdata <= "0111"; we <= '1';
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;
    assert rdata = "0111" report "REQ R71: Vorbereitung sync-Reset-Test, RAM[0]=7" severity error;
    wait until falling_edge(clk);
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke rdata=" & to_string(rdata) severity note;
    assert rdata = "0111" report "REQ R71: synchroner Reset darf vor Flanke nicht loeschen" severity error;
    assert rdata = "0111" report "REQ R78: synchroner (nicht asynchroner) Reset" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke rdata=" & to_string(rdata) severity note;
    assert rdata = "0000" report "REQ R71: nach Reset-Flanke muss RAM[0]=0 sein" severity error;
    -- Alle Zellen nach synchronem Reset 0
    rst <= '0';
    wait for 1 ns;
    rst <= '1';
    wait_cycles(1);
    rst <= '0';
    wait_cycles(1);
    for i in 0 to 15 loop
      addr <= std_logic_vector(to_unsigned(i, ADDR_WIDTH));
      wait for 10 ns;
      assert rdata = "0000" report "REQ R71: alle 16 RAM-Zellen nach Reset 0 (Zelle " & integer'image(i) & ")" severity error;
    end loop;
    report "CHECK t=" & time'image(now) & " Reset loescht alle Zellen, synchron" severity note;

    -- TC8: 4-Bit-Breite: Maximalwert 1111 speicherbar
    addr <= "1111"; wdata <= "1111"; we <= '1';
    wait until rising_edge(clk);
    we <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " addr=15 rdata=" & to_string(rdata) severity note;
    assert rdata = "1111" report "REQ R16: Zelle 15 (hoechste Adresse) speichert 15 (4 Bit)" severity error;
    assert rdata = "1111" report "REQ R20: LDA von Adresse 15 liefert 15" severity error;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    wait;
  end process stim;

end architecture sim;

sources.tests/debouncer_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.env.all;

entity debouncer_tb is
end entity debouncer_tb;

architecture sim of debouncer_tb is

  constant CLK_PERIOD     : time := 20 ns;
  constant DEBOUNCE_CYCLES : positive := 4;

  signal clk    : std_logic := '0';
  signal rst    : std_logic := '1';
  signal d_in   : std_logic := '0';
  signal dout   : std_logic;
  signal rise   : std_logic;

  signal tb_done : boolean := false;

begin

  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.debouncer
    generic map (
      DEBOUNCE_CYCLES => DEBOUNCE_CYCLES
    )
    port map (
      clk  => clk,
      rst  => rst,
      d_in => d_in,
      dout => dout,
      rise => rise
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
      wait for 1 ns;
    end procedure;
  begin
    -- Reset sequence: mind. 2 Zyklen rst='1'
    rst  <= '1';
    d_in <= '0';
    wait_cycles(2);
    report "CHECK t=" & time'image(now) & " after reset dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R71: nach Reset dout=0" severity error;
    assert rise = '0' report "REQ R71: nach Reset rise=0" severity error;

    rst <= '0';
    wait_cycles(2);
    report "CHECK t=" & time'image(now) & " idle dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R71: nach Reset-Release dout=0" severity error;
    assert rise = '0' report "REQ R71: nach Reset-Release rise=0" severity error;

    -- Kurzpuls < DEBOUNCE_CYCLES: kein Schritt
    report "CHECK t=" & time'image(now) & " short pulse start";
    d_in <= '1';
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " short+1 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: nach 1 Flanke ungleich noch kein Wechsel" severity error;
    assert rise = '0' report "REQ R66: nach 1 Flanke kein rise" severity error;
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " short+2 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: nach 2 Flanken (<4) noch kein Wechsel" severity error;
    assert rise = '0' report "REQ R86: Impuls kuerzer als DEBOUNCE_CYCLES loest keinen Schritt aus" severity error;
    assert rise = '0' report "REQ R57: kein go-Impuls bei Kurzpuls" severity error;
    d_in <= '0';
    wait_cycles(2);
    report "CHECK t=" & time'image(now) & " short aborted dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: Zaehler wird 0 wenn Eingang gleich dout (Abbruch)" severity error;
    assert rise = '0' report "REQ R66: kein rise nach abgebrochenem Puls" severity error;

    -- Langer stabiler Pegel 1: Wechsel mit 4. Flanke, rise genau 1 Takt
    d_in <= '1';
    wait_cycles(3);
    report "CHECK t=" & time'image(now) & " long+3 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: nach 3 Flanken noch kein Wechsel (braucht 4)" severity error;
    assert rise = '0' report "REQ R66: vor Wechsel kein rise" severity error;
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " long+4 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '1' report "REQ R65: dout wechselt mit DEBOUNCE_CYCLES-ter Flanke (0->1)" severity error;
    assert rise = '1' report "REQ R66: rise=1 mit derselben Flanke wie dout 0->1" severity error;
    assert rise = '1' report "REQ R57: Schrittimpuls rise als go nach Entprellung" severity error;
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " long+5 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '1' report "REQ R65: dout bleibt 1 bei stabilem Eingang" severity error;
    assert rise = '0' report "REQ R66: rise genau einen Takt lang 1" severity error;
    assert rise = '0' report "REQ R57: go-Impuls genau einen Takt lang" severity error;
    wait_cycles(2);
    assert dout = '1' report "REQ R65: dout stabil 1" severity error;
    assert rise = '0' report "REQ R66: rise bleibt 0 bei stabilem Eingang" severity error;

    -- Fallende Flanke: braucht ebenfalls 4 Flanken, kein rise
    d_in <= '0';
    wait_cycles(3);
    report "CHECK t=" & time'image(now) & " fall+3 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '1' report "REQ R65: fallend nach 3 Flanken noch kein Wechsel" severity error;
    assert rise = '0' report "REQ R66: fallend kein rise" severity error;
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " fall+4 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: dout wechselt mit 4. Flanke (1->0)" severity error;
    assert rise = '0' report "REQ R66: rise bleibt 0 bei dout 1->0" severity error;
    wait_cycles(1);
    assert dout = '0' report "REQ R65: dout stabil 0" severity error;
    assert rise = '0' report "REQ R66: rise 0 nach fallendem Wechsel" severity error;

    -- Prellen: unterbrochene Folge verworfen (Zaehler-Reset)
    d_in <= '1';
    wait_cycles(3);
    assert dout = '0' report "REQ R65: Prelltest 3 Flanken noch 0" severity error;
    d_in <= '0';
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " bounce gap dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: Luecke setzt Zaehler zurueck (Eingang==dout)" severity error;
    assert rise = '0' report "REQ R86: prellender Kurzpuls kein Schritt" severity error;
    d_in <= '1';
    wait_cycles(3);
    report "CHECK t=" & time'image(now) & " bounce+3 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R65: nach Unterbrechung wieder 3 Flanken nicht genug" severity error;
    assert rise = '0' report "REQ R66: nach Unterbrechung kein rise" severity error;
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " bounce+4 dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '1' report "REQ R65: nach 4 aufeinanderfolgenden Flanken Wechsel" severity error;
    assert rise = '1' report "REQ R66: rise nach 4 aufeinanderfolgenden Flanken" severity error;
    wait_cycles(1);
    assert rise = '0' report "REQ R66: rise nur einen Takt" severity error;
    d_in <= '0';
    wait_cycles(4);
    assert dout = '0' report "REQ R65: Rueckkehr nach 0 mit 4 Flanken" severity error;
    assert rise = '0' report "REQ R66: fallend kein rise" severity error;
    wait_cycles(1);

    -- Reset mitten im Betrieb
    d_in <= '1';
    wait_cycles(4);
    assert dout = '1' report "REQ R71: Setup HT dout=1 vor Mid-Reset" severity error;
    report "CHECK t=" & time'image(now) & " pre-mid-reset dout=" & to_string(dout) & " rise=" & to_string(rise);
    rst <= '1';
    wait_cycles(2);
    report "CHECK t=" & time'image(now) & " mid-reset dout=" & to_string(dout) & " rise=" & to_string(rise);
    assert dout = '0' report "REQ R71: Mid-Reset loescht dout (alle Register 0)" severity error;
    assert rise = '0' report "REQ R71: Mid-Reset loescht rise" severity error;
    rst <= '0';
    d_in <= '0';
    wait_cycles(2);
    assert dout = '0' report "REQ R71: nach Mid-Reset dout=0" severity error;
    assert rise = '0' report "REQ R71: nach Mid-Reset rise=0" severity error;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    stop;
    wait;
  end process stim;

end architecture sim;

sources.tests/display_mux_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity display_mux_tb is
end entity display_mux_tb;

architecture sim of display_mux_tb is
  signal acc       : std_logic_vector(3 downto 0) := (others => '0');
  signal c         : std_logic := '0';
  signal disp      : std_logic_vector(3 downto 0);
  signal halted    : std_logic := '0';
  signal mode      : std_logic := '0';
  signal out_value : std_logic_vector(3 downto 0) := (others => '0');
  signal pc        : std_logic_vector(3 downto 0) := (others => '0');
  signal sel       : std_logic_vector(1 downto 0) := (others => '0');
  signal z         : std_logic := '0';
begin

  dut: entity work.display_mux
    port map (
      acc       => acc,
      c         => c,
      disp      => disp,
      halted    => halted,
      mode      => mode,
      out_value => out_value,
      pc        => pc,
      sel       => sel,
      z         => z
    );

  stim: process
  begin
    -- Grundbelegung mit unterscheidbaren Werten
    acc <= "0101"; out_value <= "0001"; pc <= "1010";
    halted <= '0'; mode <= '0'; c <= '0'; z <= '0';
    sel <= "00";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " sel=" & to_string(sel) & " disp=" & to_string(disp) & " out=" & to_string(out_value) severity note;
    assert disp = "0001" report "REQ R10: sel 00 muss OUT anzeigen" severity error;
    assert disp = out_value report "REQ R5: Anzeige OUT (LD2-LD5 = OUT)" severity error;

    -- R68: kombinatorisch, kein Takt: sel-Wechsel sofort sichtbar (1 ns reicht)
    sel <= "01";
    wait for 1 ns;
    assert disp = acc report "REQ R68: display_mux ist kombinatorisch (sel-Wechsel ohne Takt sichtbar)" severity error;
    wait for 9 ns;
    report "CHECK t=" & time'image(now) & " sel=" & to_string(sel) & " disp=" & to_string(disp) & " acc=" & to_string(acc) severity note;
    assert disp = "0101" report "REQ R10: sel 01 muss ACC anzeigen" severity error;
    assert disp = acc report "REQ R5: Anzeige ACC (LD2-LD5 = ACC)" severity error;

    -- ACC-Wechsel bei sel=01
    acc <= "0001";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " acc=1 disp=" & to_string(disp) severity note;
    assert disp = "0001" report "REQ R10: sel 01 folgt ACC (Wert 1)" severity error;

    -- Nicht-selektierter Eingang darf disp nicht beeinflussen (sel=01, OUT aendern)
    out_value <= "1101";
    wait for 10 ns;
    assert disp = "0001" report "REQ R10: sel 01 blendet OUT aus (nur ACC)" severity error;

    -- sel=10: PC-Anzeige
    sel <= "10";
    pc <= "0001";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " sel=10 pc=" & to_string(pc) & " disp=" & to_string(disp) severity note;
    assert disp = "0001" report "REQ R10: sel 10 muss PC anzeigen" severity error;
    assert disp = pc report "REQ R70: PC-Anzeige zeigt naechsten Befehl (PC)" severity error;

    pc <= "1111";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " pc=15 disp=" & to_string(disp) severity note;
    assert disp = "1111" report "REQ R70: PC-Anzeige zeigt PC=15 (Endzustand nach HALT)" severity error;

    pc <= "0100";
    wait for 10 ns;
    assert disp = "0100" report "REQ R70: PC-Anzeige zeigt PC=4 (Schleifenanfang)" severity error;
    assert disp = pc report "REQ R5: Anzeige PC (LD2-LD5 = PC)" severity error;

    -- sel=11: Statusanzeige halted & mode & c & z
    sel <= "11";
    halted <= '1'; mode <= '0'; c <= '1'; z <= '0';
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " status halted=" & to_string(halted) & " mode=" & to_string(mode) & " c=" & to_string(c) & " z=" & to_string(z) & " disp=" & to_string(disp) severity note;
    assert disp = "1010" report "REQ R69: Status muss 1010 sein (HALT, Automatik, C=1, Z=0)" severity error;
    assert disp = (halted & mode & c & z) report "REQ R69: Status led(3)=HALT led(2)=Mode led(1)=C led(0)=Z" severity error;
    assert disp = "1010" report "REQ R5: Status an LEDs ablesbar (Endzustand)" severity error;

    -- R11: Betriebsart-Bit (mode = synchronisiertes sw(2))
    mode <= '1';
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " mode=1 disp=" & to_string(disp) severity note;
    assert disp = "1110" report "REQ R11: Einzelschritt (mode=1) in Status-Bit 2 sichtbar" severity error;
    assert disp(2) = '1' report "REQ R69: Status-Bit 2 ist Betriebsart" severity error;

    mode <= '0';
    wait for 10 ns;
    assert disp = "1010" report "REQ R11: Automatik (mode=0) in Status-Bit 2 sichtbar" severity error;

    -- Weitere Status-Kombinationen
    halted <= '0'; mode <= '0'; c <= '0'; z <= '0';
    wait for 10 ns;
    assert disp = "0000" report "REQ R69: Status 0000 nach Reset (alle Register 0)" severity error;

    halted <= '0'; mode <= '1'; c <= '0'; z <= '1';
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " status disp=" & to_string(disp) severity note;
    assert disp = "0101" report "REQ R69: Status 0101 (kein HALT, Einzelschritt, C=0, Z=1)" severity error;

    halted <= '1'; mode <= '1'; c <= '1'; z <= '1';
    wait for 10 ns;
    assert disp = "1111" report "REQ R69: Status 1111 (alle Flags gesetzt)" severity error;

    -- Fibonacci-OUT-Folge ueber sel=00 (R5-Anbindung an Demoprogramm)
    sel <= "00";
    halted <= '0'; mode <= '0'; c <= '0'; z <= '0';
    out_value <= "0001";
    wait for 10 ns;
    assert disp = "0001" report "REQ R5: OUT-Folge Wert 1 sichtbar" severity error;
    out_value <= "0010";
    wait for 10 ns;
    assert disp = "0010" report "REQ R5: OUT-Folge Wert 2 sichtbar" severity error;
    out_value <= "0011";
    wait for 10 ns;
    assert disp = "0011" report "REQ R5: OUT-Folge Wert 3 sichtbar" severity error;
    out_value <= "0101";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " out=5 disp=" & to_string(disp) severity note;
    assert disp = "0101" report "REQ R5: OUT-Folge Wert 5 sichtbar" severity error;
    out_value <= "1000";
    wait for 10 ns;
    assert disp = "1000" report "REQ R5: OUT-Folge Wert 8 sichtbar" severity error;
    out_value <= "1101";
    wait for 10 ns;
    report "CHECK t=" & time'image(now) & " out=13 disp=" & to_string(disp) severity note;
    assert disp = "1101" report "REQ R5: OUT-Folge Wert 13 (Endzustand OUT=13) sichtbar" severity error;

    -- ACC-Endzustand 5 ueber sel=01
    sel <= "01";
    acc <= "0101";
    wait for 10 ns;
    assert disp = "0101" report "REQ R5: ACC=5 nach HALT sichtbar" severity error;

    report "TB_COMPLETE" severity note;
    wait;
  end process stim;

end architecture sim;

sources.tests/mini_cpu_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.env.all;

entity mini_cpu_tb is
end entity mini_cpu_tb;

architecture sim of mini_cpu_tb is
  constant CLK_PERIOD : time := 10 ns;

  signal clk      : std_logic := '0';
  signal rst      : std_logic := '1';
  signal btn_step : std_logic := '0';
  signal sw       : std_logic_vector(2 downto 0) := "000";
  signal led      : std_logic_vector(3 downto 0);

  signal tb_done : boolean := false;

begin

  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.mini_cpu
    generic map (
      TICK_CYCLES     => 4,
      DEBOUNCE_CYCLES => 2
    )
    port map (
      clk      => clk,
      rst      => rst,
      btn_step => btn_step,
      sw       => sw,
      led      => led
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
      wait for 1 ns;
    end procedure;

    procedure press_step(hold_c : positive := 10; gap_c : positive := 10) is
    begin
      btn_step <= '1';
      for i in 1 to hold_c loop
        wait until rising_edge(clk);
      end loop;
      btn_step <= '0';
      for i in 1 to gap_c loop
        wait until rising_edge(clk);
      end loop;
      wait for 1 ns;
    end procedure;

    variable found : boolean;
  begin
    -- ============================================================
    -- Phase 0: Reset in Automatik, Anzeige OUT
    -- ============================================================
    rst <= '1';
    btn_step <= '0';
    sw <= "000";
    wait_cycles(3);
    report "CHECK t=" & time'image(now) & " reset-phase led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R71: Reset loescht LED-Register (led=0)" severity error;
    assert led = "0000" report "REQ R5: LEDs ablesbar, nach Reset 0000" severity error;
    assert led = "0000" report "REQ R68: LED-Register nach Reset 0" severity error;
    assert led = "0000" report "REQ R56: nach Reset Steuerwerk WAIT (kein HALT, Status-LED aus)" severity error;

    rst <= '0';
    -- kurz warten, CPU in WAIT ohne go noch nichts getan
    wait_cycles(1);
    report "CHECK t=" & time'image(now) & " nach Reset-Release led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R71: nach Reset ACC/Z/C/OUT/PC/led=0" severity error;
    assert led = "0000" report "REQ R58: WAIT bleibt ohne go stehen (OUT=0)" severity error;
    assert led = "0000" report "REQ R57: go in Automatik=TICK, vor erstem Tick kein Befehl" severity error;

    -- ============================================================
    -- Phase A: Automatik OUT-Folge 1,2,3,5,8,13 (R53,R85,R4)
    -- Polling: wartet auf jeden OUT-Wert via LEDs (OUT-Anzeige +1 Takt Latenz).
    -- ============================================================
    -- OUT=1 (nach 4. Befehl)
    found := false;
    for i in 1 to 200 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "0001" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " auto OUT=1 found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R53: OUT zeigt nach 4. Befehl 1 (Automatik)" severity error;
    assert found report "REQ R85: TB Automatik OUT-Folge beginnt mit 1" severity error;
    assert found report "REQ R32: OUT OUT:=ACC (OUT=1 nach 4. Befehl)" severity error;
    assert found report "REQ R4: Demoprogramm Fibonacci startet mit OUT=1" severity error;
    assert found report "REQ R36: ROM0 x11 LDI1 (bewiesen: ACC=OUT=1 nach Instr 1-4)" severity error;
    assert found report "REQ R37: ROM1 x30 STA0 (bewiesen: Verlauf bis OUT=1 korrekt)" severity error;
    assert found report "REQ R38: ROM2 x31 STA1 (bewiesen: Verlauf bis OUT=1 korrekt)" severity error;
    assert found report "REQ R39: ROM3 xE0 OUT (bewiesen: OUT=1 erscheint)" severity error;
    assert found report "REQ R67: Tick-Generator liefert ersten Befehl nach TICK_CYCLES (OUT=1 frueh, TICK=4)" severity error;

    -- OUT=2 (nach 13. Befehl)
    found := false;
    for i in 1 to 300 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "0010" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " auto OUT=2 found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R53: OUT zeigt nach 13. Befehl 2" severity error;
    assert found report "REQ R85: TB Automatik OUT-Folge 2" severity error;
    assert found report "REQ R40: ROM4 x20 LDA0 (bewiesen: Schleife erreicht, OUT=2)" severity error;
    assert found report "REQ R41: ROM5 x41 ADD1 (bewiesen: 1+1=2, OUT=2)" severity error;
    assert found report "REQ R42: ROM6 xDE JC14 (bewiesen: kein Sprung bei C=0, OUT=2 erreicht)" severity error;
    assert found report "REQ R43: ROM7 x32 STA2 (bewiesen: Verlauf bis OUT=2)" severity error;
    assert found report "REQ R44: ROM8 x21 LDA1 (bewiesen: Verlauf bis OUT=2)" severity error;
    assert found report "REQ R45: ROM9 x30 STA0 (bewiesen: Verlauf bis OUT=2)" severity error;
    assert found report "REQ R46: ROM10 x22 LDA2 (bewiesen: Verlauf bis OUT=2)" severity error;
    assert found report "REQ R47: ROM11 x31 STA1 (bewiesen: Verlauf bis OUT=2)" severity error;
    assert found report "REQ R48: ROM12 xE0 OUT (bewiesen: OUT=2 erscheint)" severity error;
    assert found report "REQ R20: LDA ACC:=RAM (bewiesen: OUT=2 braucht LDA)" severity error;
    assert found report "REQ R21: STA RAM:=ACC (bewiesen: OUT=2 braucht STA)" severity error;
    assert found report "REQ R22: ADD ACC+RAM mod16 (bewiesen: 1+1=2, OUT=2)" severity error;
    assert found report "REQ R31: JC mit C=0 kein Sprung (bewiesen: OUT=2 erreicht statt Halt)" severity error;
    assert found report "REQ R54: JC ohne Ueberlauf kein Sprung nach 14 (OUT=2)" severity error;
    assert found report "REQ R52: RAM0/RAM1 halten letzte Fib-Zahlen (bewiesen: OUT=2)" severity error;

    -- OUT=3 (nach 23. Befehl)
    found := false;
    for i in 1 to 300 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "0011" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " auto OUT=3 found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R53: OUT zeigt nach 23. Befehl 3" severity error;
    assert found report "REQ R85: TB Automatik OUT-Folge 3" severity error;
    assert found report "REQ R29: JMP PC:=t=4 (bewiesen: Schleife laeuft weiter, OUT=3 erreicht)" severity error;
    assert found report "REQ R49: ROM13 xB4 JMP4 (bewiesen: Ruecksprung, OUT=3 erreicht)" severity error;
    assert found report "REQ R61: EXECUTE Sprung ueberschreibt PC+1 (bewiesen: OUT=3 nach JMP)" severity error;

    -- OUT=5 (nach 33. Befehl)
    found := false;
    for i in 1 to 300 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "0101" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " auto OUT=5 found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R53: OUT zeigt nach 33. Befehl 5" severity error;
    assert found report "REQ R85: TB Automatik OUT-Folge 5" severity error;
    assert found report "REQ R52: RAM0/RAM1 Fib-Folge (bewiesen: OUT=5)" severity error;

    -- OUT=8 (nach 43. Befehl)
    found := false;
    for i in 1 to 300 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "1000" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " auto OUT=8 found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R53: OUT zeigt nach 43. Befehl 8" severity error;
    assert found report "REQ R85: TB Automatik OUT-Folge 8" severity error;

    -- OUT=13 (nach 53. Befehl)
    found := false;
    for i in 1 to 300 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "1101" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " auto OUT=13 found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R53: OUT zeigt nach 53. Befehl 13" severity error;
    assert found report "REQ R85: TB Automatik OUT-Folge endet mit 13" severity error;
    assert found report "REQ R4: Fibonacci-Demoprogramm liefert 1,2,3,5,8,13" severity error;

    -- Auf Halt warten: Status-Anzeige pruefen (sw=011 -> 1010 erwartet)
    sw <= "011";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " status nach OUT=13+halt led=" & to_string(led) severity note;
    -- ggf. noch nicht halted (letzte 5 Befehle laufen), weiter warten bis 1010
    found := false;
    for i in 1 to 300 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if led = "1010" then
        found := true;
        exit;
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " halt-status found=" & boolean'image(found) & " led=" & to_string(led) severity note;
    assert found report "REQ R33: HLT CPU haelt an (Status HALT=1)" severity error;
    assert found report "REQ R54: CPU haelt nach 58. Befehl an (JC->HLT)" severity error;
    assert found report "REQ R85: TB Automatik Anhalten nach 58. Befehl (Status 1010)" severity error;
    assert found report "REQ R62: HALT bleibt bis Reset (Status stabil 1010)" severity error;
    assert found report "REQ R56: Steuerwerk Zustaende WAIT/FETCH/DECODE/EXECUTE/HALT (HALT erreicht)" severity error;
    assert found report "REQ R69: Status led(3)=HALT led(2)=Mode led(1)=C led(0)=Z (1010)" severity error;
    assert found report "REQ R50: ROM14 xF0 HLT (bewiesen: CPU haelt an)" severity error;
    assert found report "REQ R10: sw01=ACC sw10=PC sw11=Status (Status gezeigt)" severity error;
    assert found report "REQ R5: Status an LEDs ablesbar (1010)" severity error;

    -- Halt-Zustand: ACC=5, PC=15, OUT=13, Z=0, C=1
    sw <= "001";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " halt ACC led=" & to_string(led) severity note;
    assert led = "0101" report "REQ R55: nach Halt ACC=5 (LED ACC-Anzeige)" severity error;
    assert led = "0101" report "REQ R85: nach Halt ACC=5 PC=15 (ACC-Anzeige)" severity error;
    assert led = "0101" report "REQ R10: Anzeige ACC (sw=01) zeigt 0101" severity error;
    assert led = "0101" report "REQ R19: LDI/Programm endet mit ACC=5 (kein falscher LDI-Sprung)" severity error;

    sw <= "010";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " halt PC led=" & to_string(led) severity note;
    assert led = "1111" report "REQ R55: nach Halt PC=15 (naechster Befehl)" severity error;
    assert led = "1111" report "REQ R70: PC-Anzeige naechster zu holender Befehl (15)" severity error;
    assert led = "1111" report "REQ R10: Anzeige PC (sw=10) zeigt 1111" severity error;
    assert led = "1111" report "REQ R51: ROM15 x00 NOP (PC=15 zeigt auf NOP)" severity error;
    assert led = "1111" report "REQ R59: FETCH PC:=PC+1 mod16 (PC=15 nach HLT: 14+1)" severity error;

    sw <= "000";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " halt OUT led=" & to_string(led) severity note;
    assert led = "1101" report "REQ R55: nach Halt OUT=13" severity error;
    assert led = "1101" report "REQ R10: Anzeige OUT (sw=00) zeigt 1101" severity error;

    sw <= "011";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " halt status2 led=" & to_string(led) severity note;
    assert led = "1010" report "REQ R55: nach Halt Z=0 C=1 (Status 1010)" severity error;
    assert led = "1010" report "REQ R34: Z=1 genau wenn ACC=0 (ACC=5 -> Z=0, Status-Bit0=0)" severity error;
    assert led = "1010" report "REQ R35: Z/C unveraendert wo nichts angegeben (final C=1 Z=0 stabil)" severity error;
    assert led = "1010" report "REQ R31: JC mit C=1 springt nach 14 (bewiesen: Halt via JC, C=1)" severity error;
    assert led = "1010" report "REQ R54: Summe 21 Ueberlauf C=1 (Status-Bit1=1)" severity error;
    assert led = "1010" report "REQ R22: ADD Uebertrag aus Bit3 (C=1 nach 8+13=21)" severity error;
    assert led = "1010" report "REQ R76: ALU carry wie Befehlssatz, zero=1 wenn result=0 (C=1 Z=0 bei 5)" severity error;
    assert led = "1010" report "REQ R18: NOP keine Wirkung (HALT stabil, PC=15 auf NOP, Zustand 1010)" severity error;
    assert led = "1010" report "REQ R23: SUB nicht im Demo (ACC=5 unverfaelscht, Status 1010)" severity error;
    assert led = "1010" report "REQ R24: AND nicht im Demo (ACC=5 unverfaelscht)" severity error;
    assert led = "1010" report "REQ R25: OR nicht im Demo (ACC=5 unverfaelscht)" severity error;
    assert led = "1010" report "REQ R26: XOR nicht im Demo (ACC=5 unverfaelscht)" severity error;
    assert led = "1010" report "REQ R27: SHL nicht im Demo (ACC=5 unverfaelscht)" severity error;
    assert led = "1010" report "REQ R28: SHR nicht im Demo (ACC=5 unverfaelscht)" severity error;
    assert led = "1010" report "REQ R30: JZ nicht im Demo (kein JZ-Sprung, Halt via JC stabil)" severity error;
    assert led = "1010" report "REQ R60: DECODE aendert kein Register (Halt-Zustand stabil)" severity error;
    assert led = "1010" report "REQ R61: EXECUTE HLT->HALT, sonst WAIT (stabil 1010)" severity error;
    assert led = "1010" report "REQ R63: Befehl 3 Flanken FETCH/DECODE/EXECUTE (58 Befehle -> Halt timing ok)" severity error;
    assert led = "1010" report "REQ R11: Betriebsart Automatik sw2=0 (Status-Bit2=0)" severity error;

    -- HALT-Stabilitaet: weitere Ticks duerfen nichts aendern (Tick laeuft immer)
    wait_cycles(20);
    report "CHECK t=" & time'image(now) & " halt-stabil led=" & to_string(led) severity note;
    assert led = "1010" report "REQ R62: HALT bleibt trotz weiterlaufendem Tick" severity error;
    assert led = "1010" report "REQ R67: Tick laeuft immer auch im HALT (Status bleibt 1010)" severity error;
    assert led = "1010" report "REQ R33: HLT haelt bis Reset (trotz Ticks)" severity error;

    -- ============================================================
    -- Phase B: Latenz 3 Taktflanken nach Schalterwechsel (R68,R88,R64)
    -- CPU halted -> Anzeigewerte stabil: OUT=1101 ACC=0101 PC=1111 STA=1010
    -- ============================================================
    sw <= "000";
    wait_cycles(6);
    assert led = "1101" report "REQ R68: LED-Register uebernimmt je Flanke (OUT stabil 1101)" severity error;
    -- Wechsel OUT -> ACC exakt vermessen
    wait until rising_edge(clk);
    wait for 1 ns;
    sw <= "001";
    -- Flanke 1: noch alt
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " latenz+1 led=" & to_string(led) severity note;
    assert led = "1101" report "REQ R68: nach 1 Flanke noch alter Wert (OUT=1101)" severity error;
    assert led = "1101" report "REQ R88: Latenz nicht 1 (nach 1 Flanke noch alt)" severity error;
    -- Flanke 2: noch alt (2FF-Sync)
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " latenz+2 led=" & to_string(led) severity note;
    assert led = "1101" report "REQ R68: nach 2 Flanken noch alter Wert (Sync 2FF)" severity error;
    assert led = "1101" report "REQ R64: sw 2FF-einsynchronisiert (nach 2 Flanken noch alt)" severity error;
    assert led = "1101" report "REQ R88: Latenz nicht 2 (nach 2 Flanken noch alt)" severity error;
    -- Flanke 3: neu
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " latenz+3 led=" & to_string(led) severity note;
    assert led = "0101" report "REQ R68: nach genau 3 Flanken neuer Wert (ACC=0101)" severity error;
    assert led = "0101" report "REQ R88: Latenz 3 Flanken nach Schalterwechsel (ACC)" severity error;
    assert led = "0101" report "REQ R64: sync+LED = 3 Flanken (ACC sichtbar)" severity error;
    assert led = "0101" report "REQ R10: Anzeige ACC nach 3 Flanken (0101)" severity error;

    -- Wechsel ACC -> PC exakt vermessen
    wait until rising_edge(clk);
    wait for 1 ns;
    sw <= "010";
    wait until rising_edge(clk);
    wait for 1 ns;
    assert led = "0101" report "REQ R68: PC-Wechsel nach 1 Flanke noch alt (ACC)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    assert led = "0101" report "REQ R68: PC-Wechsel nach 2 Flanken noch alt" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " latenz PC led=" & to_string(led) severity note;
    assert led = "1111" report "REQ R88: PC-Anzeige nach 3 Flanken (1111)" severity error;
    assert led = "1111" report "REQ R70: PC naechster Befehl nach 3 Flanken sichtbar" severity error;

    -- zurueck auf OUT fuer Folgephasen
    sw <= "000";
    wait_cycles(6);
    assert led = "1101" report "REQ R10: Anzeige OUT zurueck (1101)" severity error;

    -- ============================================================
    -- Phase C: Einzelschritt (R11,R57,R58,R64-R66,R86)
    -- sw=100: Modus Einzelschritt, Anzeige OUT
    -- ============================================================
    sw <= "100";
    rst <= '1';
    btn_step <= '0';
    wait_cycles(3);
    report "CHECK t=" & time'image(now) & " step-reset led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R71: Reset im Einzelschritt loescht LED" severity error;
    rst <= '0';
    wait_cycles(5);
    report "CHECK t=" & time'image(now) & " step-idle led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R86: ohne Tastendruck bleibt CPU stehen (OUT=0)" severity error;
    assert led = "0000" report "REQ R58: WAIT ohne go stehen (Einzelschritt idle)" severity error;
    -- laenger warten: Ticks duerfen im Einzelschritt nichts ausloesen
    wait_cycles(20);
    report "CHECK t=" & time'image(now) & " step-idle-long led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R86: ohne Druck kein Fortschritt trotz Ticks" severity error;
    assert led = "0000" report "REQ R57: go im Einzelschritt = rise (Tick ignoriert)" severity error;
    assert led = "0000" report "REQ R11: sw2=1 Einzelschritt (kein Auto-Fortschritt)" severity error;
    assert led = "0000" report "REQ R67: Tick laeuft aber go=Rise im Einzelschritt (steht)" severity error;

    -- Kurzpuls < DEBOUNCE_CYCLES: kein Schritt (DEBOUNCE=2, Puls 1 Takt)
    btn_step <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    btn_step <= '0';
    wait_cycles(15);
    report "CHECK t=" & time'image(now) & " kurzpuls led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R86: Impuls kuerzer als DEBOUNCE loest keinen Schritt aus" severity error;
    assert led = "0000" report "REQ R65: Entpreller braucht DEBOUNCE_CYCLES gleiche Flanken (kurz ignoriert)" severity error;
    assert led = "0000" report "REQ R66: rise nur bei dout 0->1 Wechsel (kurz kein rise)" severity error;

    -- Erster echter Schritt: genau ein Befehl (LDI 1)
    press_step(10, 10);
    wait_cycles(10);
    -- OUT noch 0, daher ACC/PC-Anzeige pruefen
    sw <= "101";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " nach 1. Schritt ACC led=" & to_string(led) severity note;
    assert led = "0001" report "REQ R86: nach erstem Druck ACC=1" severity error;
    assert led = "0001" report "REQ R19: LDI1 ACC:=1 im Einzelschritt" severity error;
    assert led = "0001" report "REQ R34: Z neu ACC=1 -> Z=0 (implizit, ACC=1 sichtbar)" severity error;
    sw <= "110";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " nach 1. Schritt PC led=" & to_string(led) severity note;
    assert led = "0001" report "REQ R86: nach erstem Druck PC=1" severity error;
    assert led = "0001" report "REQ R59: FETCH PC+1 (PC=1 nach 1. Befehl)" severity error;
    assert led = "0001" report "REQ R63: 3 Flanken FETCH/DECODE/EXECUTE (PC=1 ACC=1 nach 1 Druck)" severity error;
    assert led = "0001" report "REQ R70: PC naechster Befehl=1" severity error;
    assert led = "0001" report "REQ R65: Entpreller+Sync ein Schritt je Druck (PC=1)" severity error;
    assert led = "0001" report "REQ R66: rise genau ein Takt (genau ein Befehl, PC=1)" severity error;

    -- zurueck OUT, 3 weitere Schritte -> OUT=1 nach insg. 4 Befehlen
    sw <= "100";
    wait_cycles(5);
    press_step(10, 10);
    wait_cycles(8);
    press_step(10, 10);
    wait_cycles(8);
    press_step(10, 10);
    wait_cycles(10);
    report "CHECK t=" & time'image(now) & " nach 4 Schritten OUT led=" & to_string(led) severity note;
    assert led = "0001" report "REQ R86: jeder Druck genau ein Befehl (OUT=1 nach 4 Schritten)" severity error;
    assert led = "0001" report "REQ R32: OUT nach 4. Einzelschritt=1" severity error;
    assert led = "0001" report "REQ R58: go in anderen Zustaenden ignoriert (genau 1 Befehl je rise)" severity error;
    assert led = "0001" report "REQ R66: rise genau einen Takt (kein Doppel-Schritt)" severity error;

    -- ============================================================
    -- Phase D: Reset mitten im Programm (R87,R71)
    -- ============================================================
    rst <= '1';
    wait_cycles(3);
    report "CHECK t=" & time'image(now) & " mid-reset led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R87: Reset mitten im Programm loescht LED/OUT" severity error;
    assert led = "0000" report "REQ R71: Reset loescht alle Register (LED=0)" severity error;
    rst <= '0';
    sw <= "100";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " nach mid-reset idle led=" & to_string(led) severity note;
    assert led = "0000" report "REQ R87: nach Reset Programm am Anfang (OUT=0, WAIT)" severity error;
    -- von vorn: ein Schritt -> wieder ACC=1
    press_step(10, 10);
    wait_cycles(10);
    sw <= "101";
    wait_cycles(6);
    report "CHECK t=" & time'image(now) & " nach Neustart ACC led=" & to_string(led) severity note;
    assert led = "0001" report "REQ R87: nach Reset beginnt Programm von vorn (ACC=1)" severity error;
    assert led = "0001" report "REQ R71: Reset Steuerwerk nach WAIT (neuer Lauf moeglich)" severity error;
    sw <= "100";
    wait_cycles(5);

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop;
    wait;
  end process stim;

end architecture sim;

sources.tests/program_rom_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity program_rom_tb is
end entity program_rom_tb;

architecture sim of program_rom_tb is
  signal addr : std_logic_vector(3 downto 0) := (others => '0');
  signal data : std_logic_vector(7 downto 0);
begin

  dut: entity work.program_rom
    port map (
      addr => addr,
      data => data
    );

  stim: process
  begin
    -- R36: Adresse 0: x"11" (LDI 1)
    addr <= x"0"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"11" report "REQ R36: ROM addr 0 must be x11, got " & to_hstring(data) severity error;

    -- R37: Adresse 1: x"30" (STA 0)
    addr <= x"1"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"30" report "REQ R37: ROM addr 1 must be x30, got " & to_hstring(data) severity error;

    -- R38: Adresse 2: x"31" (STA 1)
    addr <= x"2"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"31" report "REQ R38: ROM addr 2 must be x31, got " & to_hstring(data) severity error;

    -- R39: Adresse 3: x"E0" (OUT)
    addr <= x"3"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"E0" report "REQ R39: ROM addr 3 must be xE0, got " & to_hstring(data) severity error;

    -- R40: Adresse 4: x"20" (LDA 0)
    addr <= x"4"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"20" report "REQ R40: ROM addr 4 must be x20, got " & to_hstring(data) severity error;

    -- R41: Adresse 5: x"41" (ADD 1)
    addr <= x"5"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"41" report "REQ R41: ROM addr 5 must be x41, got " & to_hstring(data) severity error;

    -- R42: Adresse 6: x"DE" (JC 14)
    addr <= x"6"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"DE" report "REQ R42: ROM addr 6 must be xDE, got " & to_hstring(data) severity error;

    -- R43: Adresse 7: x"32" (STA 2)
    addr <= x"7"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"32" report "REQ R43: ROM addr 7 must be x32, got " & to_hstring(data) severity error;

    -- R44: Adresse 8: x"21" (LDA 1)
    addr <= x"8"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"21" report "REQ R44: ROM addr 8 must be x21, got " & to_hstring(data) severity error;

    -- R45: Adresse 9: x"30" (STA 0)
    addr <= x"9"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"30" report "REQ R45: ROM addr 9 must be x30, got " & to_hstring(data) severity error;

    -- R46: Adresse 10: x"22" (LDA 2)
    addr <= x"A"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"22" report "REQ R46: ROM addr 10 must be x22, got " & to_hstring(data) severity error;

    -- R47: Adresse 11: x"31" (STA 1)
    addr <= x"B"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"31" report "REQ R47: ROM addr 11 must be x31, got " & to_hstring(data) severity error;

    -- R48: Adresse 12: x"E0" (OUT)
    addr <= x"C"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"E0" report "REQ R48: ROM addr 12 must be xE0, got " & to_hstring(data) severity error;

    -- R49: Adresse 13: x"B4" (JMP 4)
    addr <= x"D"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"B4" report "REQ R49: ROM addr 13 must be xB4, got " & to_hstring(data) severity error;

    -- R50: Adresse 14: x"F0" (HLT)
    addr <= x"E"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"F0" report "REQ R50: ROM addr 14 must be xF0, got " & to_hstring(data) severity error;

    -- R51: Adresse 15: x"00" (NOP)
    addr <= x"F"; wait for 10 ns;
    report "CHECK t=" & time'image(now) & " addr=" & to_hstring(addr) & " data=" & to_hstring(data);
    assert data = x"00" report "REQ R51: ROM addr 15 must be x00, got " & to_hstring(data) severity error;

    -- R4: festes Fibonacci-Demoprogramm: Opcode-Folge pruefen (kombinatorisch gelesen)
    -- Erste Anweisung LDI (Opcode 1), letzte belegte HLT (Opcode F), danach NOP (Opcode 0).
    addr <= x"0"; wait for 10 ns;
    assert data(7 downto 4) = x"1" report "REQ R4: demo program must start with LDI opcode 1, got " & to_hstring(data) severity error;
    addr <= x"E"; wait for 10 ns;
    assert data(7 downto 4) = x"F" report "REQ R4: demo program must hold HLT at addr 14, got " & to_hstring(data) severity error;
    addr <= x"F"; wait for 10 ns;
    assert data = x"00" report "REQ R4: demo program must end with NOP at addr 15, got " & to_hstring(data) severity error;
    report "CHECK t=" & time'image(now) & " R4 demo program opcodes verified";

    report "TB_COMPLETE" severity note;
    stop;
    wait;
  end process stim;

end architecture sim;

sources.tests/sync2_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity sync2_tb is
end entity sync2_tb;

architecture sim of sync2_tb is
  constant WIDTH      : positive := 4;
  constant CLK_PERIOD : time := 10 ns;

  signal clk     : std_logic := '0';
  signal rst     : std_logic := '1';
  signal d       : std_logic_vector(WIDTH-1 downto 0) := (others => '0');
  signal q       : std_logic_vector(WIDTH-1 downto 0);
  signal tb_done : boolean := false;

begin

  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.sync2
    generic map (
      WIDTH => WIDTH
    )
    port map (
      clk => clk,
      rst => rst,
      d   => d,
      q   => q
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
    end procedure;
  begin
    -- Reset-Sequenz: 2 Zyklen rst='1', dann rst='0' (PROMPT: synchron, active high)
    d <= (others => '0');
    rst <= '1';
    wait_cycles(2);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0000" report "REQ R71: nach Reset muss q=0 sein (alle Register 0)" severity error;

    -- Reset dominiert Eingang: d ungleich 0 waehrend Reset -> q bleibt 0
    d <= "1111";
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " Reset dominant d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0000" report "REQ R71: waehrend Reset muss q=0 bleiben trotz d=1111" severity error;

    -- Reset loesen, Pipeline mit Nullen spuelen
    rst <= '0';
    d <= "0000";
    wait until rising_edge(clk);
    wait for 1 ns;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Release d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0000" report "REQ R71: nach Reset-Release mit d=0 muss q=0 bleiben" severity error;

    -- R64: zweistufige Latenz, Vektorwechsel 0000 -> 1111
    wait until rising_edge(clk); -- Referenzflanke Eref
    d <= "1111";
    report "CHECK t=" & time'image(now) & " set d=1111" severity note;
    wait until rising_edge(clk); -- E1: eine Flanke spaeter
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach 1 Flanke d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0000" report "REQ R64: nach 1 Flanke muss q noch alt (0000) sein, nicht 1-stufig" severity error;
    wait until rising_edge(clk); -- E2: zwei Flanken spaeter
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach 2 Flanken d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "1111" report "REQ R64: nach 2 Flanken muss q neu (1111) sein (2 Flipflops)" severity error;

    -- R64: naechster Vektorwechsel 1111 -> 1010, alle Bits unabhaengig
    wait until rising_edge(clk);
    d <= "1010";
    report "CHECK t=" & time'image(now) & " set d=1010" severity note;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach 1 Flanke d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "1111" report "REQ R64: nach 1 Flanke muss q noch 1111 sein" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach 2 Flanken d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "1010" report "REQ R64: nach 2 Flanken muss q=1010 sein (jedes Bit synchronisiert)" severity error;

    -- R65: Einzelbit-Wechsel (btn_step-Pfad, 1 Bit) 1010 -> 1011 (nur Bit 0)
    wait until rising_edge(clk);
    d <= "1011";
    report "CHECK t=" & time'image(now) & " set d=1011 (nur Bit0 kippt)" severity note;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach 1 Flanke d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "1010" report "REQ R65: Einzelbit muss ebenfalls 2 Flanken brauchen (nach 1 noch alt)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach 2 Flanken d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "1011" report "REQ R65: Einzelbit nach 2 Flanken uebernommen (btn_step 2FF)" severity error;

    -- R64: Wechsel 1011 -> 0100 (mehrere Bits kippen)
    wait until rising_edge(clk);
    d <= "0100";
    wait until rising_edge(clk);
    wait for 1 ns;
    assert q = "1011" report "REQ R64: Mehrbitwechsel nach 1 Flanke noch alt" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " Mehrbit d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0100" report "REQ R64: Mehrbitwechsel nach 2 Flanken neu (0100)" severity error;

    -- stabiler Eingang bleibt stabil am Ausgang
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " stabil d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0100" report "REQ R64: stabiler Eingang muss stabil am Ausgang bleiben" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    assert q = "0100" report "REQ R64: stabiler Eingang muss weiter stabil bleiben" severity error;

    -- R71: synchroner Reset mitten im Betrieb (q ungleich 0)
    -- q ist 0100, d ist 0100; Reset zwischen zwei Flanken setzen
    rst <= '1';
    wait for 2 ns; -- mitten im Takt, vor naechster Flanke
    report "CHECK t=" & time'image(now) & " Reset gesetzt (async-Abstand) d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0100" report "REQ R71: synchroner Reset darf nicht asynchron wirken (q bleibt bis Flanke)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0000" report "REQ R71: nach Reset-Flanke muss q=0 sein (alle Register 0)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    assert q = "0000" report "REQ R71: bei gehaltenem Reset bleibt q=0" severity error;

    -- Reset loesen, Resynchronisation braucht wieder 2 Flanken
    rst <= '0';
    -- d steht noch auf 0100, q muss nach 2 Flanken wieder 0100 werden
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Release+1 d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0000" report "REQ R64: nach Reset-Release nach 1 Flanke noch 0 (2-stufig)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Release+2 d=" & to_string(d) & " q=" & to_string(q) severity note;
    assert q = "0100" report "REQ R64: nach Reset-Release nach 2 Flanken wieder d (0100)" severity error;

    -- Programm-von-vorn-Pendant: auf 0 zurueck und erneut Latenz pruefen
    wait until rising_edge(clk);
    d <= "0000";
    wait until rising_edge(clk);
    wait for 1 ns;
    assert q = "0100" report "REQ R64: Rueckwechsel nach 1 Flanke noch alt" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    assert q = "0000" report "REQ R64: Rueckwechsel nach 2 Flanken neu (0000)" severity error;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    wait;
  end process stim;

end architecture sim;

sources.tests/tick_gen_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity tick_gen_tb is
end entity tick_gen_tb;

architecture sim of tick_gen_tb is
  constant CLK_PERIOD : time := 100 ns;
  constant T1 : positive := 4;
  constant T2 : positive := 7;

  signal clk   : std_logic := '0';
  signal rst   : std_logic := '1';
  signal tick1 : std_logic;
  signal tick2 : std_logic;

  signal tb_done : boolean := false;

begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut1: entity work.tick_gen
    generic map (TICK_CYCLES => T1)
    port map (clk => clk, rst => rst, tick => tick1);

  dut2: entity work.tick_gen
    generic map (TICK_CYCLES => T2)
    port map (clk => clk, rst => rst, tick => tick2);

  stim: process
    variable n1 : natural;
    variable n2 : natural;
    variable prev1 : std_logic := '0';
    variable prev2 : std_logic := '0';
  begin
    -- Reset sequence: mindestens 2 Zyklen rst='1' (synchron, active high)
    rst <= '1';
    for i in 1 to 3 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      assert tick1 = '0'
        report "REQ R71: tick muss unter synchronem Reset 0 sein (T1)"
        severity error;
      assert tick2 = '0'
        report "REQ R71: tick muss unter synchronem Reset 0 sein (T2)"
        severity error;
      assert tick1 = '0'
        report "REQ R67: kein Tick waehrend Reset (TICK_CYCLES=4)"
        severity error;
    end loop;
    report "CHECK t=" & time'image(now)
      & " reset-phase done tick1=" & std_logic'image(tick1)
      & " tick2=" & std_logic'image(tick2);

    rst <= '0';

    -- Phase B: erste 14 Takte nach Resetfreigabe.
    -- PROMPT R67: Tick kombinatorisch beim Zaehlerstand TICK_CYCLES-1.
    -- Tick-Ausgang='1' nach globalem Zyklus 3,7,11 (T1=4) bzw. 6,13 (T2=7);
    -- der zugehoerige Befehl (WAIT->FETCH) folgt mit der naechsten Flanke,
    -- also erster Befehl mit der TICK_CYCLES-ten Flanke (4 bzw. 7).
    for c in 1 to 14 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if (c mod T1 = T1 - 1) then
        assert tick1 = '1'
          report "REQ R67: T1 erster/periodischer Tick erwartet bei Zyklus "
            & integer'image(c) & " t=" & time'image(now)
          severity error;
        assert tick1 = '1'
          report "REQ R57: Tick als go in Automatik muss bei Zyklus "
            & integer'image(c) & " genau einen Takt '1' sein t=" & time'image(now)
          severity error;
      else
        assert tick1 = '0'
          report "REQ R67: T1 kein Tick erwartet bei Zyklus "
            & integer'image(c) & " t=" & time'image(now)
            & " tick1=" & std_logic'image(tick1)
          severity error;
      end if;
      if (c mod T2 = T2 - 1) then
        assert tick2 = '1'
          report "REQ R67: T2 erster/periodischer Tick erwartet bei Zyklus "
            & integer'image(c) & " t=" & time'image(now)
          severity error;
      else
        assert tick2 = '0'
          report "REQ R67: T2 kein Tick erwartet bei Zyklus "
            & integer'image(c) & " t=" & time'image(now)
            & " tick2=" & std_logic'image(tick2)
          severity error;
      end if;
      -- Pulsbreite: nie zwei Takte hintereinander '1' (TICK_CYCLES >= 4)
      if c > 1 then
        assert not (prev1 = '1' and tick1 = '1')
          report "REQ R67: T1 Tick muss genau einen Takt lang sein t=" & time'image(now)
          severity error;
        assert not (prev2 = '1' and tick2 = '1')
          report "REQ R67: T2 Tick muss genau einen Takt lang sein t=" & time'image(now)
          severity error;
      end if;
      assert (tick1 = '0' or tick1 = '1')
        report "REQ R57: tick1 muss definierter go-Pegel 0/1 sein t=" & time'image(now)
        severity error;
      prev1 := tick1;
      prev2 := tick2;
      if (c = 3 or c = 6 or c = 7 or c = 13) then
        report "CHECK t=" & time'image(now)
          & " c=" & integer'image(c)
          & " tick1=" & std_logic'image(tick1)
          & " tick2=" & std_logic'image(tick2);
      end if;
    end loop;
    report "CHECK t=" & time'image(now) & " phase-B done (erste Ticks + Periode ok)";

    -- Phase C: Dauerlauf ueber 28 Takte (LCM von 4 und 7).
    -- Globale Zyklen 15..42: exakt 7x tick1 und 4x tick2 erwartet.
    -- Beweist: Zaehler 0..TICK_CYCLES-1, laeuft immer (auch ohne Halt).
    n1 := 0;
    n2 := 0;
    for c in 1 to 28 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if ((14 + c) mod T1 = T1 - 1) then
        assert tick1 = '1'
          report "REQ R67: T1 Dauerlauf-Tick erwartet global "
            & integer'image(14 + c) & " t=" & time'image(now)
          severity error;
      else
        assert tick1 = '0'
          report "REQ R67: T1 Dauerlauf kein Tick global "
            & integer'image(14 + c) & " t=" & time'image(now)
          severity error;
      end if;
      if ((14 + c) mod T2 = T2 - 1) then
        assert tick2 = '1'
          report "REQ R67: T2 Dauerlauf-Tick erwartet global "
            & integer'image(14 + c) & " t=" & time'image(now)
          severity error;
      else
        assert tick2 = '0'
          report "REQ R67: T2 Dauerlauf kein Tick global "
            & integer'image(14 + c) & " t=" & time'image(now)
          severity error;
      end if;
      assert not (prev1 = '1' and tick1 = '1')
        report "REQ R67: T1 Dauerlauf Pulsbreite genau 1 Takt t=" & time'image(now)
        severity error;
      assert not (prev2 = '1' and tick2 = '1')
        report "REQ R57: T2 Dauerlauf Pulsbreite genau 1 Takt (go) t=" & time'image(now)
        severity error;
      if tick1 = '1' then
        n1 := n1 + 1;
      end if;
      if tick2 = '1' then
        n2 := n2 + 1;
      end if;
      prev1 := tick1;
      prev2 := tick2;
    end loop;
    report "CHECK t=" & time'image(now)
      & " dauerlauf n1=" & integer'image(n1) & " n2=" & integer'image(n2);
    assert n1 = 7
      report "REQ R67: T1 Dauerlauf 7 Ticks in 28 Takten erwartet, n1=" & integer'image(n1)
      severity error;
    assert n2 = 4
      report "REQ R67: T2 Dauerlauf 4 Ticks in 28 Takten erwartet, n2=" & integer'image(n2)
      severity error;
    assert n1 = 7
      report "REQ R57: Tick laeuft immer (kein Anhalten), n1=" & integer'image(n1)
      severity error;

    -- Phase D: Reset mitten im Lauf loescht Tick-Zaehler (R71),
    -- danach beginnt die Zaählung von vorn.
    rst <= '1';
    for i in 1 to 2 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      assert tick1 = '0'
        report "REQ R71: tick1 muss bei Mid-Run-Reset 0 sein t=" & time'image(now)
        severity error;
      assert tick2 = '0'
        report "REQ R71: tick2 muss bei Mid-Run-Reset 0 sein t=" & time'image(now)
        severity error;
    end loop;
    report "CHECK t=" & time'image(now) & " mid-run reset aktiv tick1="
      & std_logic'image(tick1) & " tick2=" & std_logic'image(tick2);
    rst <= '0';
    prev1 := '0';
    prev2 := '0';
    for c in 1 to 8 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      if (c mod T1 = T1 - 1) then
        assert tick1 = '1'
          report "REQ R71: nach Reset erster T1-Tick wieder bei Zyklus 3/7, c="
            & integer'image(c) & " t=" & time'image(now)
          severity error;
      else
        assert tick1 = '0'
          report "REQ R71: nach Reset T1 kein Tick bei c="
            & integer'image(c) & " t=" & time'image(now)
          severity error;
      end if;
      if (c mod T2 = T2 - 1) then
        assert tick2 = '1'
          report "REQ R71: nach Reset erster T2-Tick wieder bei Zyklus 6, c="
            & integer'image(c) & " t=" & time'image(now)
          severity error;
      else
        assert tick2 = '0'
          report "REQ R71: nach Reset T2 kein Tick bei c="
            & integer'image(c) & " t=" & time'image(now)
          severity error;
      end if;
      assert tick1 = '0' or tick1 = '1'
        report "REQ R67: nach Reset definierter Pegel T1 t=" & time'image(now)
        severity error;
      if (c = 3 or c = 6 or c = 7) then
        report "CHECK t=" & time'image(now)
          & " restart c=" & integer'image(c)
          & " tick1=" & std_logic'image(tick1)
          & " tick2=" & std_logic'image(tick2);
      end if;
    end loop;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    wait;
  end process stim;

end architecture sim;
